const searchDecisions = `-- name: SearchDecisions :many
SELECT d.id, d.workspace_id, d.topic, d.question, d.answer, d.scope, d.source, d.run_id, d.item_id, d.created_at, d.forgotten_at, ts_rank(to_tsvector('simple'::regconfig, d.topic || ' ' || d.question || ' ' || d.answer),
  replace(plainto_tsquery('simple'::regconfig, $1::text)::text, '&', '|')::tsquery)::float8 AS rank
FROM public.decision_memory d
WHERE d.workspace_id = $2 AND d.forgotten_at IS NULL
  AND to_tsvector('simple'::regconfig, d.topic || ' ' || d.question || ' ' || d.answer)
      @@ replace(plainto_tsquery('simple'::regconfig, $1::text)::text, '&', '|')::tsquery
  AND ($3::text = '' OR d.scope->>'behavior' = $3::text)
ORDER BY rank DESC, d.created_at DESC, d.id DESC
LIMIT $4::int
`

type SearchDecisionsParams struct {
	Query       string
	WorkspaceID pgtype.UUID
	Behavior    string
	MaxRows     int32
}

type SearchDecisionsRow struct {
	ID          int64
	WorkspaceID pgtype.UUID
	Topic       string
	Question    string
	Answer      string
	Scope       []byte
	Source      string
	RunID       pgtype.Int8
	ItemID      pgtype.Int8
	CreatedAt   pgtype.Timestamptz
	ForgottenAt pgtype.Timestamptz
	Rank        float64
}

// Any query word matches (the words are OR-ed); best rank first. An empty
// behavior filter matches every scope.
func (q *Queries) SearchDecisions(ctx context.Context, arg SearchDecisionsParams) ([]SearchDecisionsRow, error) {
	rows, err := q.db.Query(ctx, searchDecisions,
		arg.Query,
		arg.WorkspaceID,
		arg.Behavior,
		arg.MaxRows,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchDecisionsRow
	for rows.Next() {
		var i SearchDecisionsRow
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.Topic,
			&i.Question,
			&i.Answer,
			&i.Scope,
			&i.Source,
			&i.RunID,
			&i.ItemID,
			&i.CreatedAt,
			&i.ForgottenAt,
			&i.Rank,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const selectBehaviorRunClaimCandidate = `-- name: SelectBehaviorRunClaimCandidate :one
SELECT id FROM public.behavior_runs
WHERE ((status = 'pending' AND run_at <= $1::timestamptz)
    OR (status = 'running' AND locked_until <= $1::timestamptz))
  AND attempts < $2::int
ORDER BY (status = 'running') DESC, run_at, id
FOR UPDATE SKIP LOCKED LIMIT 1
`

